# /// script
# dependencies = ['sympy', 'pycryptodome']
# ///
from sympy import nextprime
from Crypto.Util.number import bytes_to_long as b2l
from Crypto.Util.number import getPrime

e1 = nextprime(b2l(b'HZ'))
e2 = nextprime(b2l(b'U18'))

m1 = b2l(b'HZU18{<REDACTED>}')
m2 = m1 * e1 + e2

n = getPrime(512) * getPrime(512)

print('n =', n)
print('c1 =', pow(m1, e1, n))
print('c2 =', pow(m2, e2, n))

